"""Tasks: self-supervised training tasks generated by DocMaestro, made browsable and searchable.

DocMaestro (https://github.com/VLR-CVC/DocMaestro) turns each document's structure into tasks (OCR, layout,
caption prediction, figure selection, page sorting, ...). Its `scripts/run_doctasks.py --json-out DIR` writes one
`<doc_id>/<doc_name>_doctasks.json` per document plus `doctasks_index.json`. This module loads those files into
WORK/tasks.sqlite so the explorer can list and search them like documents and figures, and open each task at the
page it comes from:

    python -m pdfatlas.tasks --import /path/to/doctasks-json [--crops /path/to/processed]
    python -m pdfatlas.tasks --map [--gpu 3]     # the tasks map (1 task in 32, like the figure map)

--crops is DocMaestro's extraction tree (the `<doc_id>/images/...` figure crops), only needed to show crops.
Re-running replaces the previous import. Kept in its own SQLite file, like labels.sqlite: the pipeline never
writes it, and rows are keyed by the PDF *path*, so they survive a rebuild of the index.

DocMaestro documents are matched to the catalogue by path: its doc_id is the document folder relative to its root
(e.g. "wur/wur_006_thesis"), which is "<collection>/<path inside the collection, without .pdf>" when the extraction
tree mirrors the sources. A doc_id that matches nothing that way is matched by file stem, if the stem is unique.

  tasks(id, path, dm_doc, task, page, key, input, target, pages, figures, region)
      page = -1 for document-level tasks (page sorting, figure ordering); pages/figures = JSON lists of the
      page renders and figure crops the task shows the model; region = [x0,y0,x1,y1] (0..1) when the task
      points at one element of the page
  tasks_fts: FTS5 over input + target
  meta(k, v): crops root, source folder, time of the import
"""
import argparse
import json
import os
import re
import sqlite3
import time
from pathlib import Path

from . import config as C

DB = C.WORK / "tasks.sqlite"
MAX_TEXT = 4000      # characters of input / target kept per task (enough to read and search, not a copy of the corpus)

SCHEMA = """
CREATE TABLE tasks(id INTEGER PRIMARY KEY, path TEXT, dm_doc TEXT, task TEXT, page INTEGER, key TEXT,
    input TEXT, target TEXT, pages TEXT, figures TEXT, region TEXT);
CREATE INDEX tasks_task ON tasks(task, id);
CREATE INDEX tasks_path ON tasks(path, page);
CREATE VIRTUAL TABLE tasks_fts USING fts5(input, target, content='tasks', content_rowid='id',
    tokenize='unicode61 remove_diacritics 2');
CREATE TABLE meta(k TEXT PRIMARY KEY, v TEXT);
"""


def connect(readonly=False):
    if readonly:
        con = sqlite3.connect(f"file:{DB}?mode=ro", uri=True, check_same_thread=False, timeout=30)
        con.row_factory = sqlite3.Row
        return con
    return sqlite3.connect(DB, timeout=60)


def _text(v):
    if v is None:
        return ""
    s = v if isinstance(v, str) else json.dumps(v, ensure_ascii=False)
    return s[:MAX_TEXT]


def _region(meta):
    try:
        b = json.loads(meta["bbox"]) if isinstance(meta.get("bbox"), str) else meta.get("bbox")
        return json.dumps([round(float(x) / 1000, 4) for x in b]) if b and len(b) == 4 else None
    except (TypeError, ValueError):
        return None


def documents(root):
    """-> [(doc_id, json path)] from doctasks_index.json, or by walking the tree when there is none."""
    index = root / "doctasks_index.json"
    if index.exists():
        out = []
        for d in json.loads(index.read_text(encoding="utf-8")):
            p = root / d["doc_id"] / f"{d['doc_name']}_doctasks.json"
            if p.exists():
                out.append((d["doc_id"], p))
        return out
    return [(p.parent.relative_to(root).as_posix(), p) for p in sorted(root.rglob("*_doctasks.json"))]


def path_lookup():
    """-> (key 'collection/inner/path' -> catalogue path, stem -> path or None when ambiguous)."""
    import pandas as pd
    cat = pd.read_parquet(C.CATALOG, columns=["path", "collection"])
    roots = {s["name"]: Path(os.path.expanduser(s["path"])) for s in C.load_sources()}
    by_key, by_stem = {}, {}
    for path, coll in zip(cat.path, cat.collection):
        p = Path(path)
        try:
            inner = p.relative_to(roots[coll]).with_suffix("").as_posix()
        except (KeyError, ValueError):
            inner = p.stem
        by_key[_norm(f"{coll}/{inner}")] = path
        stem = _norm(p.stem)
        by_stem[stem] = None if stem in by_stem else path
    return by_key, by_stem


def _norm(name):
    """Trailing dots/spaces are dropped from folder names on some filesystems (a PDF named 'x..pdf')."""
    return "/".join(part.rstrip(". ") for part in name.split("/"))


def import_tasks(root, crops=None):
    root = Path(root)
    by_key, by_stem = path_lookup()
    tmp = DB.with_suffix(".tmp.sqlite")
    tmp.unlink(missing_ok=True)
    con = sqlite3.connect(tmp)
    con.executescript(SCHEMA)
    n_docs, n_tasks, missing = 0, 0, []
    for dm_doc, f in documents(root):
        path = by_key.get(_norm(dm_doc)) or by_stem.get(_norm(Path(dm_doc).name))
        if path is None:
            missing.append(dm_doc)
            continue
        doc = json.loads(f.read_text(encoding="utf-8"))
        rows = []
        for task, samples in doc.get("tasks", {}).items():
            for s in samples:
                if "__error__" in s:
                    continue
                meta, assets = s.get("json") or {}, s.get("assets.json") or {}
                rows.append((path, dm_doc, task, int(meta.get("page_idx", -1)), s.get("__key__", ""),
                             _text(s.get("input.json", s.get("input.txt"))),
                             _text(s.get("target.json", s.get("target.txt"))),
                             json.dumps([p["page_idx"] for p in assets.get("page_images", [])]),
                             json.dumps([p["src"] for p in assets.get("figure_images", [])]),
                             _region(meta)))
        con.executemany("INSERT INTO tasks(path,dm_doc,task,page,key,input,target,pages,figures,region) "
                        "VALUES (?,?,?,?,?,?,?,?,?,?)", rows)
        n_docs += 1
        n_tasks += len(rows)
    con.execute("INSERT INTO tasks_fts(tasks_fts) VALUES('rebuild')")
    con.executemany("INSERT INTO meta VALUES (?,?)", [("source", str(root)), ("crops", str(crops or "")),
                                                     ("t", str(time.time()))])
    con.commit()
    con.close()
    os.replace(tmp, DB)          # the server keeps reading the old file until this point
    print(f"{n_tasks} tasks from {n_docs} documents -> {DB}")
    if missing:
        print(f"{len(missing)} DocMaestro documents match no PDF in the catalogue, e.g. {missing[:3]}")


MAP_MOD = 32         # 1 task in 32 is placed on the map, like the figure map (topics.IMG_MAP_MOD)
K_TASKS = 30
MIN_WORDS_CHARS = 20  # a task needs this much text (outside tags/JSON) to be placed on the map


_JSON_TEXT = re.compile(r'"text":\s*"((?:[^"\\]|\\.)*)')
_XML_TAG = re.compile(r"<[^>]+>")
# words that are the structure of a task (JSON keys, XML tags, task names), not its content: kept out of topic names
STRUCT = {"text", "block", "tag", "bbox", "sup", "sub", "doc", "page", "idx", "title", "figure", "caption",
          "preceding", "following", "label", "level", "width", "height", "reconstruction", "layout", "ocr",
          "markdown", "tree", "reading", "order", "basic", "edition", "dom", "selection", "prediction", "sorting",
          "ordering", "img", "src", "images", "jpg", "header", "footer", "number", "table", "chart", "math"}


def _content(s):
    """The words a task carries: the "text" values of its JSON, its XML without the tags, or the string itself."""
    s = s or ""
    found = _JSON_TEXT.findall(s)       # also works on JSON cut at MAX_TEXT
    if found:
        return " ".join(found)
    if s.lstrip()[:1] in ("{", "["):    # JSON without any text (e.g. {"preceding": [], "following": []})
        return ""
    if "<" in s and ">" in s:
        return _XML_TAG.sub(" ", s)
    return s


def map_text(task, inp, target):
    """What a task is about, for the embedding: its type and the text it carries (answer first, then input)."""
    body = " ".join(x for x in (_content(target), _content(inp)) if x.strip())
    return f"{task.replace('_', ' ')}: {' '.join(body.split())}"[:2000]


def ctfidf(texts_by_topic, k, per=300):
    """Distinctive words per cluster, scored like topics.ctfidf_labels (c-TF-IDF)."""
    import re
    from collections import Counter

    import numpy as np
    from .topics import STOP
    tok = re.compile(r"[^\W\d_]{3,}", re.U)
    rng = np.random.default_rng(0)
    tf = []
    for t in range(k):
        texts = texts_by_topic.get(t, [])
        pick = rng.choice(len(texts), min(per, len(texts)), replace=False) if texts else []
        c = Counter()
        for j in pick:
            c.update(w for w in (x.lower() for x in tok.findall(texts[j])) if w not in STOP and w not in STRUCT and len(w) < 25)
        tf.append(c)
    total = Counter()
    for c in tf:
        total.update(c)
    A = sum(total.values()) / max(1, k)
    out = []
    for c in tf:
        s = sum(c.values()) or 1
        sc = {w: (v / s) * np.log(1 + A / total[w]) for w, v in c.items() if v >= 3}
        out.append([w for w, _ in sorted(sc.items(), key=lambda x: -x[1])[:8]])
    return out


def fit_map(gpu=None):
    """Tasks map, like the figure map: embed 1 task in 32 with the text model, k-means topics named by c-TF-IDF
    (plus the most common task type of each), UMAP to 2D. Stored in tasks.sqlite (task_map) + map/topics.json."""
    import time
    from collections import Counter

    import numpy as np
    import umap
    from sklearn.cluster import MiniBatchKMeans

    from . import topics
    from .embed_text import encode
    dev = "cpu"
    if gpu is not None:
        from .gpu import setup
        dev = setup(gpu)
    t0 = time.time()
    con = connect()
    rows = con.execute(f"SELECT id, task, input, target FROM tasks WHERE id % {MAP_MOD} = 0 ORDER BY id").fetchall()
    if not rows:
        raise SystemExit("no tasks imported yet: run --import first")
    n_all = len(rows)
    # tasks that carry no words (layout: tags and boxes only) would all get the same vector and be scattered at
    # random by UMAP: they stay searchable, but are left off the map
    rows = [r for r in rows if len(map_text(r[1], r[2], r[3])) - len(r[1]) - 2 >= MIN_WORDS_CHARS]
    print(f"{n_all - len(rows)} of {n_all} sampled tasks carry no text: left off the map", flush=True)
    ids = np.array([r[0] for r in rows])
    texts = [map_text(r[1], r[2], r[3]) for r in rows]
    X = np.concatenate([encode(texts[i:i + 2048], device=dev).astype(np.float32) for i in range(0, len(texts), 2048)])
    print(f"embedded {len(texts)} tasks in {time.time() - t0:.0f}s", flush=True)
    k = int(min(K_TASKS, max(6, len(ids) // 150)))
    km = MiniBatchKMeans(k, batch_size=8192, n_init=3, random_state=0).fit(X)
    lab = km.labels_
    um = umap.UMAP(n_neighbors=20, min_dist=0.08, metric="cosine", random_state=0, low_memory=True).fit(X)
    Y, _, _ = topics.norm01(um.embedding_)
    by_topic = {t: [texts[i] for i in np.nonzero(lab == t)[0]] for t in range(k)}
    words = ctfidf(by_topic, k)
    kinds = [Counter(rows[i][1] for i in np.nonzero(lab == t)[0]).most_common(1) for t in range(k)]
    labels = [([kinds[t][0][0].replace("_", " ")] if kinds[t] else []) + words[t] for t in range(k)]
    with con:
        con.execute("DROP TABLE IF EXISTS task_map")
        con.execute("CREATE TABLE task_map(id INTEGER PRIMARY KEY, topic INTEGER, mx REAL, my REAL)")
        con.executemany("INSERT INTO task_map VALUES (?,?,?,?)",
                        [(int(i), int(t), float(x), float(y)) for i, t, (x, y) in zip(ids, lab, Y)])
    C.MAP.mkdir(parents=True, exist_ok=True)
    topics.write_meta("tasks", dict(labels=labels, k=k, colors=topics.colors(k), fitted_on=int(len(ids)),
                                    version=int(time.time()), counts=np.bincount(lab, minlength=k).tolist()))
    print(f"tasks map: {len(ids)} tasks, k={k} in {time.time() - t0:.0f}s", flush=True)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--import", dest="src", help="DocMaestro --json-out directory")
    ap.add_argument("--crops", help="DocMaestro extraction tree holding <doc_id>/images/... (to show figure crops)")
    ap.add_argument("--map", action="store_true", help="(re)build the tasks map; after every --import")
    ap.add_argument("--gpu", type=int, help="GPU for --map (physical index); default: CPU")
    a = ap.parse_args()
    if not C.CATALOG.exists():
        raise SystemExit(f"no catalogue in {C.WORK}: build the index first")
    if not a.src and not a.map:
        ap.error("give --import DIR, --map, or both")
    if a.src:
        import_tasks(a.src, a.crops)
    if a.map:
        fit_map(a.gpu)


if __name__ == "__main__":
    main()
